export type MockupKind = 'environment' | 'print' | 'merch' | 'poster' | 'social' | 'art'

export interface MockupPhoto {
  slug: string
  /** WebP up to 1600px wide. */
  src: string
  /** WebP up to 800px wide, for srcSet. */
  srcSm: string
  width: number
  height: number
  widthSm: number
  /** Plain title from the source filename, the starting point for alt text. */
  title: string
  kind: MockupKind
}

const at = (path: string) => `${import.meta.env.BASE_URL}mockup-photos/${path}`

